fn put64(out: &mut [u8], slot: usize, value: i64) { out[slot*8..slot*8+8].copy_from_slice(&value.to_le_bytes()); }
#[no_mangle]
pub extern "C" fn highest_response_ratio_next(v:*const i64,n:usize,out:*mut u8,capacity:usize)->i64{
 if v.is_null()||n<3||n>129{return -1;}let input=unsafe{std::slice::from_raw_parts(v,n)};let count=input[0];if count<1||count>64||n!=1+2*count as usize{return -1;}let mut a=[0i64;64];let mut b=[0i64;64];let mut tat=[0i64;64];let mut done=[false;64];for i in 0..count as usize{a[i]=input[1+2*i];b[i]=input[2+2*i];if a[i]<0||a[i]>100000||b[i]<1||b[i]>1000{return -1;}}for i in 1..count as usize{let mut j=i;while j>0&&a[j]<a[j-1]{a.swap(j,j-1);b.swap(j,j-1);j-=1;}}if count as usize*8>capacity||(count>0&&out.is_null()){return -2;}let mut now=0i64;let mut finished=0;while finished<count as usize{let mut best:Option<usize>=None;let mut best_num=0i64;for i in 0..count as usize{if !done[i]&&a[i]<=now{let candidate=now-a[i]+b[i];if best.is_none()||candidate*b[best.unwrap()]>best_num*b[i]{best=Some(i);best_num=candidate;}}}if best.is_none(){let mut earliest:Option<usize>=None;for i in 0..count as usize{if !done[i]&&(earliest.is_none()||a[i]<a[earliest.unwrap()]){earliest=Some(i);}}now=a[earliest.unwrap()];}else{let k=best.unwrap();tat[k]=now+b[k]-a[k];now+=b[k];done[k]=true;finished+=1;}}let output=unsafe{std::slice::from_raw_parts_mut(out,count as usize*8)};for i in 0..count as usize{put64(output,i,tat[i]);}(count*8)as i64
}
